using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using BetterBestiary.Skills;
using Newtonsoft.Json;
using Xunit;

namespace BetterBestiary.Tests;

/// <summary>
/// Golden parity test: the C# <see cref="SkillEffectFormatter"/> must reproduce the
/// website's <c>formatSkillEffect</c> output for every exported skill. The corpus
/// (<c>Fixtures/skill-effect-parity.json</c>) is generated by
/// <c>pnpm --filter website gen:skill-effect-parity</c> and embedded into this assembly.
/// If this fails, the port drifted from the TypeScript source of truth. Fix the
/// port (or regenerate the corpus after an intentional TS change).
/// </summary>
public class SkillEffectFormatterTests
{
    private sealed class ParityCase
    {
        public string skill_id { get; set; } = "";
        public SkillEffectInput input { get; set; } = new();
        public string expected { get; set; } = "";
    }

    private static List<ParityCase> LoadCases()
    {
        var assembly = typeof(SkillEffectFormatterTests).Assembly;
        using var stream = assembly.GetManifestResourceStream("skill-effect-parity.json")
            ?? throw new InvalidOperationException(
                "skill-effect-parity.json not embedded; run `pnpm --filter website gen:skill-effect-parity`.");
        using var reader = new StreamReader(stream);
        var settings = new JsonSerializerSettings { Converters = { new LinearValueConverter() } };
        return JsonConvert.DeserializeObject<List<ParityCase>>(reader.ReadToEnd(), settings)
            ?? throw new InvalidOperationException("parity corpus deserialized to null");
    }

    [Fact]
    public void FormatterMatchesWebsiteCorpus()
    {
        var cases = LoadCases();
        Assert.NotEmpty(cases);

        var mismatches = new List<string>();
        foreach (var c in cases)
        {
            var actual = SkillEffectFormatter.Format(c.input);
            if (actual != c.expected)
                mismatches.Add($"  {c.skill_id}: expected «{c.expected}» got «{actual}»");
        }

        Assert.True(
            mismatches.Count == 0,
            $"{mismatches.Count}/{cases.Count} skills diverged from the website formatter:\n"
                + string.Join("\n", mismatches.Take(40)));
    }

    [Fact]
    public void MonsterContextDropsTheReadersAttributeNotes()
    {
        var skill = LoadCases().Single(c => c.skill_id == "venom_of_the_grave").input;
        Assert.Contains("per Intelligence", SkillEffectFormatter.Format(skill));
        Assert.DoesNotContain("per Intelligence", SkillEffectFormatter.Format(skill, monsterContext: true));
    }

    [Fact]
    public void MonsterContextDescribesEnrageLikeTheWebsite()
    {
        var skill = new SkillEffectInput
        {
            skill_type = "passive",
            is_enrage = true,
        };

        Assert.Equal(
            SkillEffectFormatter.Format(skill),
            SkillEffectFormatter.Format(skill, monsterContext: true));
    }

    [Fact]
    public void MonsterContextOmitsThreatThatOnlyPlayersRaise()
    {
        var skill = LoadCases().Single(c => c.skill_id == "taunt").input;
        Assert.Contains("aggro", SkillEffectFormatter.Format(skill));
        Assert.DoesNotContain("aggro", SkillEffectFormatter.Format(skill, monsterContext: true));
    }

    [Theory]
    [InlineData(1234.5, 1234.5, "+1,235 × rank Attack Power")]
    [InlineData(-1234.5, -5, "−1,235 − 5 × (rank − 1) Attack Power")]
    [InlineData(0, 2, "0 + 2 × (rank − 1) Hit Points")]
    public void StatAmountsUseCataloguePrecisionAndSignedRankFormulas(
        double baseValue, double bonusPerLevel, string expected)
    {
        var value = new LinearValue(baseValue, bonusPerLevel);
        var skill = new SkillEffectInput
        {
            skill_type = "passive",
            damage_bonus = baseValue == 0 ? null : value,
            health_max_bonus = baseValue == 0 ? value : null,
        };

        Assert.Equal(expected, SkillEffectFormatter.Format(skill));
    }

    [Fact]
    public void PercentBonusesUseValueFirstNamesAndMaximumPoolRates()
    {
        var skill = new SkillEffectInput
        {
            skill_type = "passive",
            damage_percent_bonus = new LinearValue(0.02, 0),
            health_percent_per_second_bonus = new LinearValue(0.03, 0),
            mana_percent_per_second_bonus = new LinearValue(0.04, 0),
            energy_percent_per_second_bonus = new LinearValue(0.05, 0),
        };

        Assert.Equal(
            "+2% Attack Power, +3% of maximum Hit Points per second, +4% of maximum Mana per second, +5% of maximum Rage per second",
            SkillEffectFormatter.Format(skill));
    }

    [Fact]
    public void RegenerationKeepsDecimalPrecisionAndSignedManaDrain()
    {
        var skill = new SkillEffectInput
        {
            skill_type = "target_debuff",
            healing_per_second_bonus = new LinearValue(-1234.567, 0),
            mana_per_second_bonus = new LinearValue(-2.345, 0),
            energy_per_second_bonus = new LinearValue(1.234, 0),
        };

        Assert.Equal(
            "1,234.57 dmg/s, −2.35 Mana Regeneration, +1.23 Rage Regeneration",
            SkillEffectFormatter.Format(skill));
    }
}
